CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE,name TEXT,salt BLOB,pw BLOB,created REAL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER);
CREATE TABLE IF NOT EXISTS farms(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER,name TEXT,region TEXT,lat REAL,lon REAL,practice TEXT,priorities TEXT DEFAULT '[]',is_demo INTEGER DEFAULT 0,demo_metrics TEXT,rotation TEXT DEFAULT '[]',likes_back INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS fields(id INTEGER PRIMARY KEY AUTOINCREMENT,farm_id INTEGER,name TEXT,polygon TEXT,area_ha REAL,soil TEXT,soil_source TEXT,crops TEXT DEFAULT '[]',lat REAL,lon REAL);
CREATE TABLE IF NOT EXISTS snapshots(id INTEGER PRIMARY KEY AUTOINCREMENT,field_id INTEGER,label TEXT,taken TEXT,metrics TEXT,harmony REAL,level TEXT);
CREATE TABLE IF NOT EXISTS swipes(from_farm INTEGER,to_farm INTEGER,liked INTEGER,PRIMARY KEY(from_farm,to_farm));
CREATE TABLE IF NOT EXISTS matches(id INTEGER PRIMARY KEY AUTOINCREMENT,farm_a INTEGER,farm_b INTEGER,created REAL,UNIQUE(farm_a,farm_b));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,match_id INTEGER,sender_farm INTEGER,kind TEXT DEFAULT 'text',body TEXT,payload TEXT,created REAL,read INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS tracks(id INTEGER PRIMARY KEY AUTOINCREMENT,farm_id INTEGER,snapshot_id INTEGER,kind TEXT,title TEXT,level TEXT,harmony REAL,file TEXT,info TEXT,created REAL);
CREATE TABLE IF NOT EXISTS saved_tracks(user_id INTEGER,track_id INTEGER,PRIMARY KEY(user_id,track_id));
